(7568666, 1214674, 114285, '<td valign="top">This is so beautiful it would have to be the winner, the simplicity is perfect.</td>', 'This is so beautiful it would have to be the winner, the simplicity is perfect.', '2018-05-18 02:05:22.000000', NULL, 1),
