(7568733, 1214846, 65234, '<td valign="top">Pretty sky. Looks a little washed out on my monitor; I think it would be more dramatic if it were darker and had more contrast.</td>', 'Pretty sky. Looks a little washed out on my monitor; I think it would be more dramatic if it were darker and had more contrast.', '2018-05-19 09:45:40.000000', NULL, 1),
(7568734, 1214674, 65234, '<td valign="top">Beautiful. The vignette adds a lot to the interest of the negative space.</td>', 'Beautiful. The vignette adds a lot to the interest of the negative space.', '2018-05-19 09:46:31.000000', NULL, 1),
(7568735, 1214540, 65234, '<td valign="top">Love crabapples! They make for lovely bokeh.</td>', 'Love crabapples! They make for lovely bokeh.', '2018-05-19 09:47:28.000000', NULL, 1),
(7568736, 1214627, 65234, '<td valign="top">Fun tilt to this; it really emphasizes the bokeh in the foreground. The horse is looking a little dark to me but that could be my monitor.</td>', 'Fun tilt to this; it really emphasizes the bokeh in the foreground. The horse is looking a little dark to me but that could be my monitor.', '2018-05-19 09:49:22.000000', NULL, 1),
(7568737, 1214821, 65234, '<td valign="top">That swirl in the water adds enormously to the compositional balance of this, to my eye. Makes a nice frame for the boats.</td>', 'That swirl in the water adds enormously to the compositional balance of this, to my eye. Makes a nice frame for the boats.', '2018-05-19 09:50:57.000000', NULL, 1),
(7568738, 1214783, 65234, '<td valign="top">Love the acrobatic squirrel! Too me, that''s the "wow" of the photo. The background does add nice context.</td>', 'Love the acrobatic squirrel! Too me, that''s the "wow" of the photo. The background does add nice context.', '2018-05-19 09:52:03.000000', NULL, 1),
(7568739, 1214628, 65234, '<td valign="top">Cool flower; not a lot of negative space here.</td>', 'Cool flower; not a lot of negative space here.', '2018-05-19 09:53:20.000000', NULL, 1),
